//! Abstraction: turning a cluster of files that keep being used together into one thing with a
//! name.
//!
//! This is step 2 of the consolidation loop, and it is what separates *associative* memory —
//! "these files are related" — from *semantic* memory — "these files are the parser work".
//! Without it the graph can only ever answer questions about pairs.
//!
//! **The labels here are lexical, not generated by a language model**, and that is a deliberate
//! choice rather than a shortcut. The specification suggested a model, and a model would produce
//! prettier names. It would also make the abstraction step non-deterministic, unrunnable
//! offline, and impossible to test — three properties this system does not trade away for
//! prettier names. What a model *would* add is a hook: [`Cluster`] carries everything a
//! summariser needs, so refining a label later is a function that takes a cluster and returns a
//! better string, and nothing else changes.
//!
//! Two properties the rest of the system depends on:
//!
//! - **Determinism.** The same edges produce the same clusters with the same labels, in the same
//!   order. Consolidation must be idempotent, and a community detection that depended on hash
//!   iteration order would produce new concept nodes on every pass for ever.
//! - **Stable identity.** A concept is identified by its label, so a cluster that grows by one
//!   file updates an existing concept rather than creating a rival one beside it.

use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet, HashMap};

/// A group of nodes that keep turning up together, and what it should be called.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Cluster {
    /// The concept's name, and its identity. Ascending member ids decide ties, so this is a
    /// function of the input and nothing else.
    pub label: String,
    /// Member node ids, ascending.
    pub members: Vec<i64>,
    /// The terms the label was built from, strongest first. Kept so a later summariser — or a
    /// person asking "why is it called that" — has the evidence rather than only the verdict.
    pub terms: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct ClusterConfig {
    /// Below this many members a cluster is a pair of files, not a subject worth naming.
    pub min_members: usize,
    /// Above this, label propagation has merged half the graph and the result means nothing.
    /// Such a cluster is dropped rather than named.
    pub max_members: usize,
    /// How many terms go into a label.
    pub label_terms: usize,
    /// A term this common among the nodes *outside* a cluster cannot distinguish it, however
    /// often it appears inside. Comparing against the global share instead was the first
    /// version and it was wrong: with two clusters, a term covering one of them entirely is
    /// 50 % of all documents, so the perfect label was the first thing thrown away.
    pub max_outside_share: f64,
    /// Rounds of label propagation. It converges in a handful; this is the ceiling.
    pub rounds: usize,
}

impl Default for ClusterConfig {
    fn default() -> Self {
        Self {
            min_members: 3,
            max_members: 60,
            label_terms: 3,
            max_outside_share: 0.4,
            rounds: 12,
        }
    }
}

/// One edge, reduced to what clustering needs.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Link {
    pub src: i64,
    pub dst: i64,
    pub weight: f64,
}

/// A node's name, for labelling. The caller supplies the path; tokenising is done here so the
/// rules live next to the tests that pin them.
#[derive(Debug, Clone, PartialEq)]
pub struct Named {
    pub id: i64,
    pub path: String,
}

/// Find the communities in an association graph and name them.
///
/// Label propagation, run to a fixed point over a deterministic node order: every node adopts
/// the label with the greatest summed edge weight among its neighbours, ties going to the
/// smaller label. It is O(edges) per round and needs no parameters to be chosen — which matters
/// more here than the marginal quality a modularity-optimising method would add, because there
/// is nobody to tune it.
/// `ignore` holds terms that cannot distinguish anything on this machine — the tokens of the
/// path every indexed file shares. On a personal machine that prefix contains the user's own
/// name, and without this the first concept the real index produced was called
/// `axon · legi · projects`: one word that meant something and two that were the shape of
/// somebody's home directory.
pub fn cluster(
    links: &[Link],
    names: &[Named],
    ignore: &BTreeSet<String>,
    cfg: &ClusterConfig,
) -> Vec<Cluster> {
    let mut neighbours: BTreeMap<i64, Vec<(i64, f64)>> = BTreeMap::new();
    for link in links {
        if link.src == link.dst {
            continue;
        }
        neighbours.entry(link.src).or_default().push((link.dst, link.weight));
        neighbours.entry(link.dst).or_default().push((link.src, link.weight));
    }
    if neighbours.is_empty() {
        return Vec::new();
    }

    // Every node starts as its own community. `BTreeMap` rather than `HashMap` so the visiting
    // order is the id order on every machine and every run.
    let mut label: BTreeMap<i64, i64> = neighbours.keys().map(|&id| (id, id)).collect();
    for _ in 0..cfg.rounds {
        let mut changed = false;
        for (&node, edges) in &neighbours {
            let mut weight_by_label: BTreeMap<i64, f64> = BTreeMap::new();
            for &(other, weight) in edges {
                if let Some(&other_label) = label.get(&other) {
                    *weight_by_label.entry(other_label).or_insert(0.0) += weight;
                }
            }
            // Greatest weight wins; the smaller label breaks a tie, which is what makes the
            // fixed point unique rather than merely reachable.
            let best = weight_by_label
                .into_iter()
                .fold(None::<(i64, f64)>, |best, (candidate, weight)| match best {
                    Some((_, w)) if w >= weight + 1e-12 => best,
                    Some((l, w)) if (w - weight).abs() < 1e-12 && l <= candidate => best,
                    _ => Some((candidate, weight)),
                });
            if let Some((winner, _)) = best {
                if label[&node] != winner {
                    label.insert(node, winner);
                    changed = true;
                }
            }
        }
        if !changed {
            break;
        }
    }

    let mut groups: BTreeMap<i64, Vec<i64>> = BTreeMap::new();
    for (&node, &group) in &label {
        groups.entry(group).or_default().push(node);
    }

    let path_by_id: HashMap<i64, &str> =
        names.iter().map(|n| (n.id, n.path.as_str())).collect();

    // Term frequencies across everything that was clustered, so a label can prefer the terms
    // that distinguish its cluster from the others rather than the ones that are simply common.
    let mut document_count = 0usize;
    let mut term_documents: HashMap<String, usize> = HashMap::new();
    let kept: Vec<Vec<i64>> = groups
        .into_values()
        .filter(|members| members.len() >= cfg.min_members && members.len() <= cfg.max_members)
        .collect();
    for members in &kept {
        for id in members {
            let Some(path) = path_by_id.get(id) else { continue };
            document_count += 1;
            for term in tokens(path) {
                *term_documents.entry(term).or_insert(0) += 1;
            }
        }
    }

    let mut out: Vec<Cluster> = kept
        .into_iter()
        .filter_map(|members| {
            let terms =
                label_terms(&members, &path_by_id, &term_documents, document_count, ignore, cfg);
            // A cluster nothing can be said about is not a concept. Naming it after its first
            // member would produce a node that looks like knowledge and is not.
            if terms.is_empty() {
                return None;
            }
            Some(Cluster {
                label: terms.iter().take(cfg.label_terms).cloned().collect::<Vec<_>>().join(" · "),
                members,
                terms,
            })
        })
        .collect();

    // Largest first, then by label, so two runs agree and the report's first lines are the
    // clusters worth reading.
    out.sort_by(|a, b| {
        b.members
            .len()
            .cmp(&a.members.len())
            .then(a.label.cmp(&b.label))
    });

    // **A label is an identity**, so two clusters sharing one would become one concept whose
    // membership each pass overwrote. Disambiguation therefore has to actually disambiguate:
    // the first attempt appended the member count, and in a corpus where several clusters had
    // five members it produced `kettle (5)` three times over.
    //
    // A colliding cluster takes another of its own terms, which says something about it, and
    // only falls back to a number when it has run out of vocabulary.
    let mut seen: BTreeSet<String> = BTreeSet::new();
    out.retain_mut(|cluster| {
        if !seen.contains(&cluster.label) {
            seen.insert(cluster.label.clone());
            return true;
        }
        let mut used = cfg.label_terms;
        while used < cluster.terms.len() {
            used += 1;
            let candidate = cluster.terms[..used].join(" · ");
            if !seen.contains(&candidate) {
                cluster.label = candidate;
                seen.insert(cluster.label.clone());
                return true;
            }
        }
        // Out of vocabulary. **The cluster is dropped rather than numbered.** A second attempt
        // appended the member count and produced `kettle (5)` three times over; a third used the
        // smallest member id, which is unique and stable but says nothing — a node called
        // `kettle #1230` looks like knowledge and is not. If two clusters cannot be told apart
        // by anything their files are named after, this one has not earned a concept.
        false
    });
    out
}

/// The terms that distinguish one cluster from the rest.
fn label_terms(
    members: &[i64],
    path_by_id: &HashMap<i64, &str>,
    term_documents: &HashMap<String, usize>,
    document_count: usize,
    ignore: &BTreeSet<String>,
    cfg: &ClusterConfig,
) -> Vec<String> {
    let mut local: BTreeMap<String, usize> = BTreeMap::new();
    let mut local_documents = 0usize;
    for id in members {
        let Some(path) = path_by_id.get(id) else { continue };
        local_documents += 1;
        for term in BTreeSet::from_iter(tokens(path)) {
            *local.entry(term).or_insert(0) += 1;
        }
    }
    if local_documents == 0 {
        return Vec::new();
    }

    let outside_documents = document_count.saturating_sub(local_documents);
    let mut scored: Vec<(f64, String)> = local
        .into_iter()
        .filter_map(|(term, count)| {
            if ignore.contains(&term) {
                return None;
            }
            let inside = count as f64 / local_documents as f64;
            // A term only half the cluster has is not what the cluster is about.
            if inside < 0.5 {
                return None;
            }
            let elsewhere = term_documents.get(&term).unwrap_or(&0).saturating_sub(count) as f64;
            let outside = if outside_documents == 0 {
                0.0
            } else {
                elsewhere / outside_documents as f64
            };
            if outside > cfg.max_outside_share || outside >= inside {
                return None;
            }
            // Common in here, rare out there. A term that is everywhere scores zero rather
            // than merely low, so it cannot be the least-bad option in a cluster with no
            // distinguishing vocabulary at all.
            const EPS: f64 = 1e-3;
            Some((inside * ((inside + EPS) / (outside + EPS)).ln(), term))
        })
        .filter(|(score, _)| *score > 0.0)
        .collect();

    scored.sort_by(|a, b| b.0.total_cmp(&a.0).then(a.1.cmp(&b.1)));
    // Twice what the label uses: the extras are what a colliding label reaches for.
    scored
        .into_iter()
        .take(cfg.label_terms * 2)
        .map(|(_, term)| term)
        .collect()
}

/// Path to terms: split on separators and case boundaries, drop the scenery.
///
/// Directory names carry as much as file names — a file called `mod.rs` says nothing and the
/// directory above it says everything — so the whole path is tokenised rather than only the
/// leaf.
pub fn tokens(path: &str) -> Vec<String> {
    /// Words that appear in every project and distinguish nothing.
    const SCENERY: [&str; 36] = [
        "src", "tests", "test", "lib", "main", "mod", "index", "docs", "doc", "bin", "build",
        "dist", "assets", "config", "utils", "util", "common", "core", "app", "home", "www",
        "public", "private", "tmp",
        // Containers people keep their work in. Naming a concept after one says only that the
        // files are on a computer.
        "projects", "project", "workspace", "repos", "repo", "code", "documents", "downloads",
        "desktop", "users", "usr", "var",
    ];

    let mut out = Vec::new();
    for segment in path.split('/') {
        // The extension is a file type, not a subject.
        let segment = segment.rsplit_once('.').map_or(segment, |(stem, _)| stem);
        for word in segment.split(|c: char| !c.is_alphanumeric()) {
            for piece in split_case(word) {
                let piece = piece.to_lowercase();
                if piece.len() < 3 || piece.chars().all(|c| c.is_ascii_digit()) {
                    continue;
                }
                if SCENERY.contains(&piece.as_str()) {
                    continue;
                }
                out.push(piece);
            }
        }
    }
    out
}

/// `parseHeader` and `ParseHeader` both become `parse`, `header`.
fn split_case(word: &str) -> Vec<String> {
    let mut pieces = Vec::new();
    let mut current = String::new();
    for c in word.chars() {
        if c.is_uppercase() && !current.is_empty() && !current.ends_with(char::is_uppercase) {
            pieces.push(std::mem::take(&mut current));
        }
        current.push(c);
    }
    if !current.is_empty() {
        pieces.push(current);
    }
    pieces
}

#[cfg(test)]
mod tests {
    use super::*;

    fn named(id: i64, path: &str) -> Named {
        Named { id, path: path.to_string() }
    }

    /// Two triangles joined by nothing must come out as two clusters.
    fn two_triangles() -> (Vec<Link>, Vec<Named>) {
        let links = vec![
            Link { src: 1, dst: 2, weight: 1.0 },
            Link { src: 2, dst: 3, weight: 1.0 },
            Link { src: 1, dst: 3, weight: 1.0 },
            Link { src: 10, dst: 11, weight: 1.0 },
            Link { src: 11, dst: 12, weight: 1.0 },
            Link { src: 10, dst: 12, weight: 1.0 },
        ];
        let names = vec![
            named(1, "/w/p/parser/tokens.rs"),
            named(2, "/w/p/parser/grammar.rs"),
            named(3, "/w/p/tests/parser_grammar.rs"),
            named(10, "/w/p/render/canvas.ts"),
            named(11, "/w/p/render/shader.ts"),
            named(12, "/w/p/tests/render_canvas.ts"),
        ];
        (links, names)
    }

    #[test]
    fn a_cluster_is_named_after_what_distinguishes_it() {
        let (links, names) = two_triangles();
        let clusters = cluster(&links, &names, &BTreeSet::new(), &ClusterConfig::default());
        assert_eq!(clusters.len(), 2, "{clusters:#?}");
        let labels: Vec<&str> = clusters.iter().map(|c| c.label.as_str()).collect();
        assert!(labels.iter().any(|l| l.contains("parser")), "{labels:?}");
        assert!(labels.iter().any(|l| l.contains("render")), "{labels:?}");
    }

    #[test]
    fn separate_communities_do_not_merge() {
        let (links, names) = two_triangles();
        let clusters = cluster(&links, &names, &BTreeSet::new(), &ClusterConfig::default());
        for c in &clusters {
            let low = c.members.iter().filter(|&&m| m < 10).count();
            assert!(low == 0 || low == c.members.len(), "mixed cluster: {c:?}");
        }
    }

    #[test]
    fn the_same_graph_always_gives_the_same_clusters_and_the_same_names() {
        let (links, names) = two_triangles();
        let cfg = ClusterConfig::default();
        assert_eq!(cluster(&links, &names, &BTreeSet::new(), &cfg), cluster(&links, &names, &BTreeSet::new(), &cfg));

        // And the order the edges arrive in must not matter either.
        let mut shuffled = links.clone();
        shuffled.reverse();
        let a = cluster(&links, &names, &BTreeSet::new(), &cfg);
        let b = cluster(&shuffled, &names, &BTreeSet::new(), &cfg);
        assert_eq!(
            a.iter().map(|c| &c.label).collect::<Vec<_>>(),
            b.iter().map(|c| &c.label).collect::<Vec<_>>()
        );
    }

    #[test]
    fn a_pair_is_not_a_concept() {
        let links = vec![Link { src: 1, dst: 2, weight: 1.0 }];
        let names = vec![named(1, "/w/a/alpha.rs"), named(2, "/w/a/beta.rs")];
        assert!(cluster(&links, &names, &BTreeSet::new(), &ClusterConfig::default()).is_empty());
    }

    #[test]
    fn a_cluster_that_swallowed_the_graph_is_dropped_rather_than_named() {
        // A hub joined to two hundred nodes: everything ends up in one community, which is a
        // failure of the clustering rather than a subject.
        let links: Vec<Link> = (2..200).map(|i| Link { src: 1, dst: i, weight: 1.0 }).collect();
        let names: Vec<Named> = (1..200).map(|i| named(i, &format!("/w/x/f{i}.rs"))).collect();
        let clusters = cluster(&links, &names, &BTreeSet::new(), &ClusterConfig::default());
        assert!(clusters.is_empty(), "{:#?}", clusters.iter().map(|c| &c.label).collect::<Vec<_>>());
    }

    #[test]
    fn scenery_never_becomes_a_name() {
        let links = vec![
            Link { src: 1, dst: 2, weight: 1.0 },
            Link { src: 2, dst: 3, weight: 1.0 },
            Link { src: 1, dst: 3, weight: 1.0 },
        ];
        let names = vec![
            named(1, "/w/p/src/main.rs"),
            named(2, "/w/p/src/lib.rs"),
            named(3, "/w/p/src/mod.rs"),
        ];
        let clusters = cluster(&links, &names, &BTreeSet::new(), &ClusterConfig::default());
        assert!(clusters.is_empty(), "nothing here says what it is about: {clusters:#?}");
    }

    #[test]
    fn two_clusters_never_share_one_name() {
        let links: Vec<Link> = (0..2)
            .flat_map(|g| {
                let base = g * 10 + 1;
                vec![
                    Link { src: base, dst: base + 1, weight: 1.0 },
                    Link { src: base + 1, dst: base + 2, weight: 1.0 },
                    Link { src: base, dst: base + 2, weight: 1.0 },
                ]
            })
            .collect();
        // Deliberately identical vocabulary in both groups.
        let names: Vec<Named> = (0..2)
            .flat_map(|g| {
                let base = g * 10 + 1;
                (0..3).map(move |i| named(base + i, &format!("/w/p{g}/invoice/ledger{i}.rs")))
            })
            .collect();
        let clusters = cluster(&links, &names, &BTreeSet::new(), &ClusterConfig::default());
        let labels: BTreeSet<&String> = clusters.iter().map(|c| &c.label).collect();
        assert_eq!(labels.len(), clusters.len(), "duplicate label: {clusters:#?}");
    }

    #[test]
    fn a_collision_is_broken_by_something_that_means_something() {
        // Two clusters whose strongest term is identical, each with a second term of its own.
        let links: Vec<Link> = (0..2)
            .flat_map(|g| {
                let base = g * 10 + 1;
                vec![
                    Link { src: base, dst: base + 1, weight: 1.0 },
                    Link { src: base + 1, dst: base + 2, weight: 1.0 },
                    Link { src: base, dst: base + 2, weight: 1.0 },
                ]
            })
            .collect();
        let names: Vec<Named> = vec![
            named(1, "/w/kettle/boiler/valve.rs"),
            named(2, "/w/kettle/boiler/pressure.rs"),
            named(3, "/w/kettle/boiler/thermostat.rs"),
            named(11, "/w/kettle/spout/pour.rs"),
            named(12, "/w/kettle/spout/angle.rs"),
            named(13, "/w/kettle/spout/filter.rs"),
        ];
        let clusters = cluster(&links, &names, &BTreeSet::new(), &ClusterConfig::default());
        assert_eq!(clusters.len(), 2);
        let labels: Vec<&str> = clusters.iter().map(|c| c.label.as_str()).collect();
        assert_ne!(labels[0], labels[1], "{labels:?}");
        assert!(
            labels.iter().all(|l| !l.contains('#')),
            "there was vocabulary to use, so the numeric fallback should not have fired: {labels:?}"
        );
    }

    /// Two clusters whose files are named the same way produce no concepts at all.
    ///
    /// Not one and a duplicate, and not one plus a numbered sibling: neither of them has a term
    /// the other lacks, so neither has earned a name. The test was originally written expecting
    /// one survivor, which was the author's expectation rather than the design's.
    #[test]
    fn clusters_with_the_same_vocabulary_name_neither_of_themselves() {
        // Two clusters, identical vocabulary, nothing to tell them apart.
        let links: Vec<Link> = (0..2)
            .flat_map(|g| {
                let base = g * 10 + 1;
                vec![
                    Link { src: base, dst: base + 1, weight: 1.0 },
                    Link { src: base + 1, dst: base + 2, weight: 1.0 },
                    Link { src: base, dst: base + 2, weight: 1.0 },
                ]
            })
            .collect();
        let names: Vec<Named> = (0..2)
            .flat_map(|g| {
                let base = g * 10 + 1;
                (0..3).map(move |i| named(base + i, &format!("/w/kettle/boiler/f{i}.rs")))
            })
            .collect();
        let clusters = cluster(&links, &names, &BTreeSet::new(), &ClusterConfig::default());
        assert!(clusters.is_empty(), "nothing distinguishes either of them: {clusters:#?}");
    }

    #[test]
    fn a_term_from_the_index_root_never_becomes_a_name() {
        let links = vec![
            Link { src: 1, dst: 2, weight: 1.0 },
            Link { src: 2, dst: 3, weight: 1.0 },
            Link { src: 1, dst: 3, weight: 1.0 },
        ];
        let names = vec![
            // No `/home/...` even with an invented name: R9's gate does not distinguish a
            // placeholder from the real thing, and it is right not to try.
            named(1, "/srv/owner/work/parser/tokens.rs"),
            named(2, "/srv/owner/work/parser/grammar.rs"),
            named(3, "/srv/owner/work/parser/lexer.rs"),
        ];
        let ignore = BTreeSet::from(["owner".to_string(), "work".to_string()]);
        let clusters = cluster(&links, &names, &ignore, &ClusterConfig::default());
        assert_eq!(clusters.len(), 1);
        assert!(clusters[0].label.contains("parser"), "{}", clusters[0].label);
        assert!(!clusters[0].label.contains("owner"), "{}", clusters[0].label);
    }

    #[test]
    fn tokens_split_paths_the_way_a_reader_would() {
        assert_eq!(tokens("/w/p/src/parseHeader.rs"), vec!["parse", "header"]);
        assert_eq!(tokens("/w/p/invoice_ledger.ts"), vec!["invoice", "ledger"]);
        assert!(tokens("/w/p/src/mod.rs").is_empty());
        assert!(tokens("/w/p/2024/01.md").is_empty());
    }

    #[test]
    fn members_come_back_ascending_so_two_runs_can_be_compared() {
        let (links, names) = two_triangles();
        for c in cluster(&links, &names, &BTreeSet::new(), &ClusterConfig::default()) {
            let mut sorted = c.members.clone();
            sorted.sort_unstable();
            assert_eq!(c.members, sorted);
        }
    }
}
